/** 获取 SSL 证书列表请求参数。 */
export interface DescribeCertificatesParams {
    /** 分页偏移量，从 0 开始。 */
    Offset?: number;
    /** 每页数量，范围为 1 至 1000。 */
    Limit?: number;
    /** 模糊匹配证书 ID、备注名称或证书域名。 */
    SearchKey?: string;
    /** 证书类型：CA 为客户端证书，SVR 为服务器证书。 */
    CertificateType?: 'CA' | 'SVR';
    /** 项目 ID。 */
    ProjectId?: number;
    /** 按证书到期时间排序。 */
    ExpirationSort?: 'ASC' | 'DESC';
    /** 证书状态筛选。 */
    CertificateStatus?: number[];
    /** 是否仅返回可部署证书：1 是，0 否。 */
    Deployable?: 0 | 1;
    /** 是否仅返回上传托管证书：1 是，0 否。 */
    Upload?: 0 | 1;
    /** 是否仅返回可续期证书：1 是，0 否。 */
    Renew?: 0 | 1;
    /** 来源筛选。 */
    FilterSource?: 'upload' | 'buy';
    /** 是否仅返回国密证书：1 是，0 否。 */
    IsSM?: 0 | 1;
    /** 是否仅返回即将过期证书：1 是，0 否。 */
    FilterExpiring?: 0 | 1;
    /** 是否仅返回可托管证书：1 是，0 否。 */
    Hostable?: 0 | 1;
    /** 标签筛选条件。 */
    Tags?: Array<{
        TagKey: string;
        TagValue?: string;
    }>;
    /** 是否仅返回等待签发证书：1 是，0 否。 */
    IsPendingIssue?: 0 | 1;
    /** 指定证书 ID 列表。 */
    CertIds?: string[];
    /** 订阅服务 ID。 */
    ServiceId?: string;
}
